async function main() {
  console.log('\n' + '═'.repeat(55));
  console.log('  White Cap Sync — 20260714 (v3)');
  console.log('  Tasks: 313 | Projects: 62');
  console.log('═'.repeat(55) + '\n');

  await supa('GET', 'projects?select=id&limit=1');
  console.log('✓ Supabase connected');
  let localOk = false, localCols = new Set();
  try {
    await pgRun('SELECT 1'); localOk = true;
    localCols = await getLocalCols();
    console.log('✓ Local PostgreSQL connected');
    console.log(`  Local columns: ${[...localCols].filter(c=>['det_weight','notes'].includes(c)).join(', ')||'(det_weight/notes not yet migrated — will skip)'}`);
  } catch(e) { console.warn('⚠ Local PG unavailable:', e.message); }

  const hasDetWeight = localCols.has('det_weight');
  const hasNotes = localCols.has('notes');

  // ── Load users ──
  const users = await supa('GET', 'users?select=id,name,username,role');
  const byName = {};
  for (const u of users) {
    byName[u.name.toLowerCase().trim()] = u;
    if (u.username) byName[u.username.toLowerCase().trim()] = u;
  }

  // ── Auto-create missing users ──
  const needed = new Set();
  for (const r of ALL_ROWS) {
    [r.detailer, r.checker, r.assignee].forEach(f => {
      if (f) f.split('/').forEach(n => { if (n.trim()) needed.add(n.trim()); });
    });
  }
  for (const name of needed) {
    if (!name || byName[name.toLowerCase()]) continue;
    const username = name.toLowerCase().replace(/\s+/g,'_');
    try {
      const [nu] = await supa('POST','users',{name,username,password:'RDSTechserv@2026',role:'Rebar',client_name:'',email:''});
      byName[name.toLowerCase()] = nu; byName[username] = nu;
      console.log(`  ➕ Created user: ${name}`);
    } catch(e) { console.warn(`  ⚠ Could not create user "${name}":`, e.message); }
  }

  // ── Load existing DB state ──
  const dbProjects = await supa('GET', `projects?client=eq.${encodeURIComponent(CLIENT_NAME)}&select=id,name,client`);
  const dbProjMap = {};
  for (const p of dbProjects) dbProjMap[`${CLIENT_NAME}||${p.name}`.toLowerCase().trim()] = p;

  const dbTasks = dbProjects.length
    ? await supa('GET', `tasks?project_id=in.(${dbProjects.map(p=>p.id).join(',')})&select=id,project_id,title,scope`)
    : [];
  const dbTaskMap = {};
  for (const t of dbTasks) dbTaskMap[`${t.project_id}||${t.title}||${t.scope||''}`.toLowerCase().trim()] = t;

  console.log(`\n  DB: ${dbProjects.length} projects, ${dbTasks.length} tasks`);

  const byProject = {};
  for (const r of ALL_ROWS) {
    if (!byProject[r.project]) byProject[r.project] = { ci: r._ci, tasks: [] };
    byProject[r.project].tasks.push(r);
  }

  let pC=0,pU=0,pD=0,tC=0,tU=0,tD=0;
  const touchedProjIds = new Set();
  const touchedTaskIds = new Set();

  for (const [projName, {ci, tasks}] of Object.entries(byProject)) {
    const pKey = `${CLIENT_NAME}||${projName}`.toLowerCase().trim();
    const existing = dbProjMap[pKey];
    const projPayload = { name:projName, client:CLIENT_NAME, color:COLORS[ci%COLORS.length], description:'', assigned_users:[], deadline:null };
    let projId;

    if (existing) {
      await supa('PATCH', `projects?id=eq.${existing.id}`, projPayload);
      projId = existing.id; pU++;
      if (localOk) await pgRun('UPDATE projects SET name=$1,client=$2,color=$3 WHERE id=$4',[projName,CLIENT_NAME,projPayload.color,projId]).catch(e=>console.warn('⚠ local proj update:',e.message));
    } else {
      projId = uuid();
      await supa('POST','projects',{id:projId,...projPayload});
      pC++;
      if (localOk) await pgRun('INSERT INTO projects (id,name,client,color,description,assigned_users,deadline) VALUES ($1,$2,$3,$4,$5,$6,$7) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name',[projId,projName,CLIENT_NAME,projPayload.color,'','{}',null]).catch(e=>console.warn('⚠ local proj insert:',e.message));
    }
    touchedProjIds.add(projId);

    for (const r of tasks) {
      const tKey = `${projId}||${r.title}||${r.scope||''}`.toLowerCase().trim();
      const et = dbTaskMap[tKey];
      const au = byName[(r.assignee||'').toLowerCase().trim()];
      const du = byName[(r.detailer||'').toLowerCase().split('/')[0].trim()];
      const cu = byName[(r.checker||'').toLowerCase().split('/')[0].trim()];
      // Supabase payload — always include all known columns
      const tp = {
        project_id:projId, title:r.title, scope:r.scope||'', status:r.status, priority:r.priority,
        assignee:au?.name||r.assignee||'', detailer:du?.name||r.detailer||'', checker:cu?.name||r.checker||'',
        client:CLIENT_NAME, client_sub_date:r.client_sub_date, due_date:r.due_date,
        det_weight:r.det_weight!==null&&r.det_weight!==undefined?r.det_weight:null,
        tags:[], files:[],
      };
      let taskId;
      if (et) {
        await supa('PATCH',`tasks?id=eq.${et.id}`,tp); taskId=et.id; tU++;
        if (localOk) {
          // Build dynamic UPDATE based on available local columns
          const sets = ['title=$1','status=$2','priority=$3','assignee=$4','detailer=$5','checker=$6','scope=$7','client_sub_date=$8','due_date=$9','client=$10'];
          const vals = [r.title,r.status,r.priority,tp.assignee,tp.detailer,tp.checker,r.scope||'',r.client_sub_date,r.due_date,CLIENT_NAME];
          if (hasDetWeight) { sets.push(`det_weight=$${vals.length+1}`); vals.push(r.det_weight); }
          vals.push(et.id);
          await pgRun(`UPDATE tasks SET ${sets.join(',')} WHERE id=$${vals.length}`, vals).catch(e=>console.warn('⚠ local task update:',e.message));
        }
      } else {
        taskId=uuid(); await supa('POST','tasks',{id:taskId,...tp}); tC++;
        if (localOk) {
          const cols = ['id','project_id','title','status','priority','assignee','detailer','checker','scope','client_sub_date','due_date','client','tags','files'];
          const vals = [taskId,projId,r.title,r.status,r.priority,tp.assignee,tp.detailer,tp.checker,r.scope||'',r.client_sub_date,r.due_date,CLIENT_NAME,'{}','{}'];
          if (hasDetWeight) { cols.push('det_weight'); vals.push(r.det_weight); }
          const placeholders = cols.map((_,i)=>`$${i+1}`).join(',');
          await pgRun(`INSERT INTO tasks (${cols.join(',')}) VALUES (${placeholders}) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,status=EXCLUDED.status`, vals).catch(e=>console.warn('⚠ local task insert:',e.message));
        }
      }
      touchedTaskIds.add(taskId);
    }

    for (const dt of dbTasks.filter(t=>t.project_id===projId)) {
      if (!touchedTaskIds.has(dt.id)) {
        await supa('DELETE',`tasks?id=eq.${dt.id}`); tD++;
        if (localOk) await pgRun('DELETE FROM tasks WHERE id=$1',[dt.id]).catch(()=>{});
      }
    }
  }

  for (const dp of dbProjects) {
    if (!touchedProjIds.has(dp.id)) {
      await supa('DELETE',`tasks?project_id=eq.${dp.id}`);
      await supa('DELETE',`projects?id=eq.${dp.id}`); pD++;
      if (localOk) { await pgRun('DELETE FROM tasks WHERE project_id=$1',[dp.id]).catch(()=>{});await pgRun('DELETE FROM projects WHERE id=$1',[dp.id]).catch(()=>{}); }
      console.log(`  🗑 Removed project not in Excel: "${dp.name}"`);
    }
  }

  console.log('\n' + '═'.repeat(55));
  console.log('  ✅ White Cap Sync Complete');
  console.log(`  Projects : +${pC} created / ~${pU} updated / -${pD} removed`);
  console.log(`  Tasks    : +${tC} created / ~${tU} updated / -${tD} removed`);
  console.log(`  Local DB : ${localOk?'✓ synced':'⚠ skipped'}`);
  if (!hasDetWeight) console.log('  ⚠ det_weight skipped in local DB — restart server to run migration, then re-sync');
  console.log('═'.repeat(55) + '\n');
  await pool.end().catch(()=>{});
}

main().catch(e=>{ console.error('\n❌ Fatal:', e.message); process.exit(1); });
